1	package rules
2	
3	import (
4		"bufio"
5		"context"
6		"fmt"
7		"os"
8		"path/filepath"
9		"regexp"
10		"strings"
11	
12		"github.com/eljakani/ward/internal/config"
13		"github.com/eljakani/ward/internal/models"
14	)
15	
16	// Scanner executes YAML-defined custom rules against the project.
17	type Scanner struct {
18		rules []config.RuleDefinition
19	}
20	
21	// New creates a rules scanner with the given rule definitions.
22	func New(rules []config.RuleDefinition) *Scanner {
23		return &Scanner{rules: rules}
24	}
25	
26	func (s *Scanner) Name() string        { return "rules-scanner" }
27	func (s *Scanner) Description() string { return "Custom YAML rule checks" }
28	
29	func (s *Scanner) Scan(_ context.Context, project models.ProjectContext, emit func(models.Finding)) ([]models.Finding, error) {
30		var findings []models.Finding
31	
32		for _, rule := range s.rules {
33			if !rule.Enabled {
34				continue
35			}
36	
37			rf := s.evaluateRule(rule, project.RootPath)
38			for _, f := range rf {
39				findings = append(findings, f)
40				emit(f)
41			}
42		}
43	
44		return findings, nil
45	}
46	
47	func (s *Scanner) evaluateRule(rule config.RuleDefinition, root string) []models.Finding {
48		var findings []models.Finding
49	
50		for _, pat := range rule.Patterns {
51			pf := s.evaluatePattern(rule, pat, root)
52			findings = append(findings, pf...)
53		}
54	
55		return findings
56	}
57	
58	func (s *Scanner) evaluatePattern(rule config.RuleDefinition, pat config.PatternDef, root string) []models.Finding {
59		switch pat.Type {
60		case "file-exists":
61			return s.checkFileExists(rule, pat, root)
62		case "regex", "contains":
63			return s.checkFileContent(rule, pat, root)
64		case "regex-scoped":
65			return s.checkScopedFileContent(rule, pat, root)
66		default:
67			return nil
68		}
69	}
70	
71	// checkFileExists looks for files matching the pattern glob.
72	func (s *Scanner) checkFileExists(rule config.RuleDefinition, pat config.PatternDef, root string) []models.Finding {
73		matches, _ := filepath.Glob(filepath.Join(root, pat.Pattern))
74		found := len(matches) > 0
75	
76		// Negative = finding if pattern is ABSENT
77		if pat.Negative {
78			if found {
79				return nil
80			}
81			return []models.Finding{s.buildFinding(rule, pat.Pattern, 0, "")}
82		}
83	
84		// Normal = finding if file exists
85		if !found {
86			return nil
87		}
88	
89		var findings []models.Finding
90		for _, m := range matches {
91			rel, _ := filepath.Rel(root, m)
92			findings = append(findings, s.buildFinding(rule, rel, 0, ""))
93		}
94		return findings
95	}
96	
97	// checkFileContent scans target files line-by-line for pattern matches.
98	func (s *Scanner) checkFileContent(rule config.RuleDefinition, pat config.PatternDef, root string) []models.Finding {
99		files := resolveTarget(pat.Target, root)
100		if len(files) == 0 {
101			return nil
102		}
103	
104		var re *regexp.Regexp
105		if pat.Type == "regex" {
106			var err error
107			re, err = regexp.Compile(pat.Pattern)
108			if err != nil {
109				return nil // skip invalid regex
110			}
111		}
112	
113		var findings []models.Finding
114	
115		for _, fpath := range files {
116			matches := scanFile(fpath, pat, re)
117	
118			rel, _ := filepath.Rel(root, fpath)
119	
120			if pat.Negative {
121				// Finding if pattern was NOT found in this file
122				if len(matches) == 0 {
123					findings = append(findings, s.buildFinding(rule, rel, 0, ""))
124				}
125			} else {
126				for _, m := range matches {
127					findings = append(findings, s.buildFinding(rule, rel, m.line, m.text))
128				}
129			}
130		}
131	
132		return findings
133	}
134	
135	type match struct {
136		line int
137		text string
138	}
139	
140	func scanFile(path string, pat config.PatternDef, re *regexp.Regexp) []match {
141		f, err := os.Open(path)
142		if err != nil {
143			return nil
144		}
145		defer f.Close()
146	
147		// Compile exclude pattern if set
148		var excludeRe *regexp.Regexp
149		if pat.ExcludePattern != "" {
150			excludeRe, _ = regexp.Compile(pat.ExcludePattern)
151		}
152	
153		var matches []match
154		scanner := bufio.NewScanner(f)
155		lineNum := 0
156		for scanner.Scan() {
157			lineNum++
158			line := scanner.Text()
159	
160			var matched bool
161			switch pat.Type {
162			case "regex":
163				matched = re.MatchString(line)
164			case "contains":
165				matched = strings.Contains(line, pat.Pattern)
166			}
167	
168			// Skip if the line also matches the exclude pattern
169			if matched && excludeRe != nil && excludeRe.MatchString(line) {
170				matched = false
171			}
172	
173			if matched {
174				matches = append(matches, match{line: lineNum, text: strings.TrimSpace(line)})
175			}
176		}
177	
178		return matches
179	}
180	
181	// resolveTarget converts a target name to a list of file paths.
182	func resolveTarget(target, root string) []string {
183		patterns := targetGlobs(target, root)
184	
185		var files []string
186		seen := make(map[string]bool)
187	
188		for _, pat := range patterns {
189			matches, _ := filepath.Glob(pat)
190			for _, m := range matches {
191				if seen[m] {
192					continue
193				}
194				info, err := os.Stat(m)
195				if err != nil || info.IsDir() {
196					continue
197				}
198				seen[m] = true
199				files = append(files, m)
200			}
201		}
202	
203		// For recursive targets, also walk subdirectories
204		if needsWalk(target) {
205			ext := targetExt(target)
206			if ext != "" {
207				_ = filepath.Walk(root, func(path string, info os.FileInfo, err error) error {
208					if err != nil {
209						return nil
210					}
211					if info.IsDir() {
212						if skipDir(info.Name()) {
213							return filepath.SkipDir
214						}
215						return nil
216					}
217					if matchesExt(path, ext) && !seen[path] {
218						seen[path] = true
219						files = append(files, path)
220					}
221					return nil
222				})
223			}
224		}
225	
226		return files
227	}
228	
229	func targetGlobs(target, root string) []string {
230		switch target {
231		case "php-files":
232			return []string{filepath.Join(root, "*.php"), filepath.Join(root, "app", "*.php")}
233		case "blade-files":
234			return []string{filepath.Join(root, "resources", "views", "*.blade.php")}
235		case "config-files":
236			return []string{filepath.Join(root, "config", "*.php")}
237		case "env-files":
238			return []string{filepath.Join(root, ".env"), filepath.Join(root, ".env.*")}
239		case "routes-files":
240			return []string{filepath.Join(root, "routes", "*.php")}
241		case "migration-files":
242			return []string{filepath.Join(root, "database", "migrations", "*.php")}
243		case "js-files":
244			return []string{filepath.Join(root, "resources", "js", "*.js"), filepath.Join(root, "resources", "js", "*.ts")}
245		default:
246			// If target looks like a glob pattern, use it directly
247			if strings.ContainsAny(target, "*?[") {
248				return []string{filepath.Join(root, target)}
249			}
250			return nil
251		}
252	}
253	
254	func needsWalk(target string) bool {
255		switch target {
256		case "php-files", "blade-files", "js-files":
257			return true
258		default:
259			return false
260		}
261	}
262	
263	func targetExt(target string) string {
264		switch target {
265		case "php-files":
266			return ".php"
267		case "blade-files":
268			return ".blade.php"
269		case "js-files":
270			return ".js" // also matches .jsx below
271		default:
272			return ""
273		}
274	}
275	
276	func matchesExt(path, ext string) bool {
277		if ext == ".php" {
278			return strings.HasSuffix(path, ".php")
279		}
280		if ext == ".blade.php" {
281			return strings.HasSuffix(path, ".blade.php")
282		}
283		if ext == ".js" {
284			return strings.HasSuffix(path, ".js") || strings.HasSuffix(path, ".ts") ||
285				strings.HasSuffix(path, ".jsx") || strings.HasSuffix(path, ".tsx")
286		}
287		return strings.HasSuffix(path, ext)
288	}
289	
290	func skipDir(name string) bool {
291		switch name {
292		case "vendor", "node_modules", ".git", "storage", ".idea", ".vscode":
293			return true
294		}
295		return false
296	}
297	
298	// checkScopedFileContent is like checkFileContent but suppresses matches that
299	// fall inside a brace-delimited scope opened by a line matching pat.ScopeExclude.
300	func (s *Scanner) checkScopedFileContent(rule config.RuleDefinition, pat config.PatternDef, root string) []models.Finding {
301		files := resolveTarget(pat.Target, root)
302		if len(files) == 0 {
303			return nil
304		}
305	
306		re, err := regexp.Compile(pat.Pattern)
307		if err != nil {
308			return nil
309		}
310	
311		var scopeRe *regexp.Regexp
312		if pat.ScopeExclude != "" {
313			scopeRe, err = regexp.Compile(pat.ScopeExclude)
314			if err != nil {
315				return nil
316			}
317		}
318	
319		var excludeRe *regexp.Regexp
320		if pat.ExcludePattern != "" {
321			excludeRe, _ = regexp.Compile(pat.ExcludePattern)
322		}
323	
324		var findings []models.Finding
325	
326		for _, fpath := range files {
327			lines, err := readLines(fpath)
328			if err != nil {
329				continue
330			}
331	
332			protected := buildProtectedRanges(lines, scopeRe)
333			rel, _ := filepath.Rel(root, fpath)
334	
335			var matched []match
336			for i, line := range lines {
337				lineNum := i + 1
338				if protected[lineNum] {
339					continue
340				}
341				if !re.MatchString(line) {
342					continue
343				}
344				if excludeRe != nil && excludeRe.MatchString(line) {
345					continue
346				}
347				matched = append(matched, match{line: lineNum, text: strings.TrimSpace(line)})
348			}
349	
350			if pat.Negative {
351				if len(matched) == 0 {
352					findings = append(findings, s.buildFinding(rule, rel, 0, ""))
353				}
354			} else {
355				for _, m := range matched {
356					findings = append(findings, s.buildFinding(rule, rel, m.line, m.text))
357				}
358			}
359		}
360	
361		return findings
362	}
363	
364	// buildProtectedRanges returns a set of line numbers (1-based) that fall inside
365	// a brace-depth scope opened by a line matching scopeRe. Lines where braces
366	// appear inside single- or double-quoted strings are ignored to avoid skew.
367	func buildProtectedRanges(lines []string, scopeRe *regexp.Regexp) map[int]bool {
368		protected := make(map[int]bool)
369		if scopeRe == nil {
370			return protected
371		}
372	
373		n := len(lines)
374		i := 0
375		for i < n {
376			line := lines[i]
377			lineNum := i + 1
378	
379			if scopeRe.MatchString(line) {
380				// Count net braces on the triggering line itself.
381				depth := countBraces(line)
382	
383				if depth > 0 {
384					// Scope opened on this line; mark from next line onward.
385					protected[lineNum] = true
386					j := i + 1
387					for j < n && depth > 0 {
388						depth += countBraces(lines[j])
389						if depth > 0 {
390							protected[j+1] = true
391						}
392						j++
393					}
394					i = j
395					continue
396				}
397				// Scope opener without a brace yet — scan forward for the opening {.
398				protected[lineNum] = true
399				j := i + 1
400				for j < n {
401					depth += countBraces(lines[j])
402					protected[j+1] = true
403					if depth > 0 {
404						j++
405						// Now consume until depth returns to 0.
406						for j < n && depth > 0 {
407							depth += countBraces(lines[j])
408							if depth > 0 {
409								protected[j+1] = true
410							}
411							j++
412						}
413						break
414					}
415					j++
416				}
417				i = j
418				continue
419			}
420			i++
421		}
422	
423		return protected
424	}
425	
426	// countBraces returns the net brace depth contribution of a line,
427	// ignoring braces inside single- or double-quoted string literals.
428	func countBraces(line string) int {
429		depth := 0
430		inSingle := false
431		inDouble := false
432		for k := 0; k < len(line); k++ {
433			ch := line[k]
434			if ch == '\\' && (inSingle || inDouble) {
435				k++ // skip escaped character
436				continue
437			}
438			switch {
439			case ch == '\'' && !inDouble:
440				inSingle = !inSingle
441			case ch == '"' && !inSingle:
442				inDouble = !inDouble
443			case ch == '{' && !inSingle && !inDouble:
444				depth++
445			case ch == '}' && !inSingle && !inDouble:
446				depth--
447			}
448		}
449		return depth
450	}
451	
452	// readLines reads all lines of a file into a string slice.
453	func readLines(path string) ([]string, error) {
454		f, err := os.Open(path)
455		if err != nil {
456			return nil, err
457		}
458		defer f.Close()
459	
460		var lines []string
461		sc := bufio.NewScanner(f)
462		for sc.Scan() {
463			lines = append(lines, sc.Text())
464		}
465		return lines, sc.Err()
466	}
467	
468	func (s *Scanner) buildFinding(rule config.RuleDefinition, file string, line int, snippet string) models.Finding {
469		return models.Finding{
470			ID:          rule.ID,
471			Title:       rule.Title,
472			Description: rule.Description,
473			Severity:    parseSeverity(rule.Severity),
474			Category:    rule.Category,
475			Scanner:     s.Name(),
476			File:        file,
477			Line:        line,
478			CodeSnippet: truncate(snippet, 200),
479			Remediation: rule.Remediation,
480			References:  rule.References,
481		}
482	}
483	
484	func parseSeverity(s string) models.Severity {
485		switch strings.ToLower(s) {
486		case "critical":
487			return models.SeverityCritical
488		case "high":
489			return models.SeverityHigh
490		case "medium":
491			return models.SeverityMedium
492		case "low":
493			return models.SeverityLow
494		default:
495			return models.SeverityInfo
496		}
497	}
498	
499	func truncate(s string, max int) string {
500		if len(s) <= max {
501			return s
502		}
503		return s[:max] + fmt.Sprintf("... (%d chars)", len(s))
504	}
